if len(board) == 0 {
	return
}
nrows := len(board)
ncols := len(board[0])

// DFS to mark 'O's connected to the border as safe (use 'S')
var dfs func(r, c int)
dfs = func(r, c int) {
	if r < 0 || r >= nrows || c < 0 || c >= ncols || board[r][c] != 'O' {
		return
	}
	board[r][c] = 'S'
	dfs(r+1, c)
	dfs(r-1, c)
	dfs(r, c+1)
	dfs(r, c-1)
}

// Start DFS from all border 'O's
for r := 0; r < nrows; r++ {
	dfs(r, 0)
	dfs(r, ncols-1)
}
for c := 0; c < ncols; c++ {
	dfs(0, c)
	dfs(nrows-1, c)
}

// Flip: 'O' → 'X' (captured), 'S' → 'O' (safe, restore)
for r := 0; r < nrows; r++ {
	for c := 0; c < ncols; c++ {
		if board[r][c] == 'O' {
			board[r][c] = 'X'
		} else if board[r][c] == 'S' {
			board[r][c] = 'O'
		}
	}
}
